(() => {
 'use strict';
 const S=window.ScenarioMath,A=window.CraftApp,market=window.FeatureMarket.create(),$=id=>document.getElementById(id);
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=(n,d=2)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d});
 const servers={europe:'Europe',west:'Americas',east:'Asia'};
 let data,loadError='',busy=false,lastRows=[],request=0;
 try{data=S.read(localStorage)}catch(e){data={version:1,items:[],selected:[]};loadError=e.message+' Данные сохранены; новые варианты временно недоступны.';}
 const launch=document.createElement('button');launch.className='button';launch.id='scenario-library';launch.type='button';launch.textContent='Мои расчёты';
 document.querySelector('.header-actions').insertBefore(launch,document.querySelector('.desktop-updates'));
 const dialog=document.createElement('dialog');dialog.id='scenario-dialog';dialog.className='scenario-dialog';
 dialog.innerHTML=`<div class="scenario-heading"><div><span class="eyebrow">ЛИЧНЫЕ ВАРИАНТЫ КРАФТА</span><h2>Мои крафты</h2></div><button type="button" id="scenario-close" class="button" aria-label="Закрыть мои расчёты">Закрыть</button></div><div class="scenario-tabs" role="tablist"><button class="button" id="scenario-saved-tab" role="tab" aria-controls="scenario-saved-panel" aria-selected="true">Сохранённые варианты</button><button class="button" id="scenario-compare-tab" role="tab" aria-controls="scenario-compare-panel" aria-selected="false">Сравнение партий</button></div><p id="scenario-status" class="hint" role="status" aria-live="polite"></p><section id="scenario-saved-panel" role="tabpanel" aria-labelledby="scenario-saved-tab"><p id="scenario-current" class="hint"></p><form id="scenario-save-form" class="scenario-save-form"><label class="field">Название варианта<input id="scenario-name" maxlength="80" required placeholder="Например, жаркое на один день"></label><button class="button primary" type="submit" id="scenario-save">Сохранить текущий расчёт</button></form><p class="hint">Сохраняются рецепт, объём, место производства, налоги и ручные цены. Мастерства и автоматические цены берутся на момент сравнения. Можно сохранить до 100 вариантов.</p><div id="scenario-list"></div></section><section id="scenario-compare-panel" role="tabpanel" aria-labelledby="scenario-compare-tab" hidden><div class="scenario-compare-tools"><label class="field">Лучший вариант по<select id="scenario-metric"><option value="unitProfit">Прибыли за штуку</option><option value="profit">Прибыли за всю партию</option><option value="roi">Доходности</option><option value="unitCost">Минимальной себестоимости штуки</option></select></label><button class="button" id="scenario-refresh">Обновить цены сравнения</button><button class="button" id="scenario-csv">Экспорт сравнения CSV</button></div><p class="hint">Добавьте партии из блока действий крафта или отметьте 2–4 варианта на вкладке сохранённых расчётов. Сравнение использует текущие мастерства и один сервер. Ручные цены остаются индивидуальными для каждого варианта. Обновление цен сравнения сохраняет открытый расчёт.</p><div id="scenario-comparison"></div></section>`;
 document.body.append(dialog);
 const tools=document.createElement('div');tools.className='batch-tools';tools.id='batch-tools';
 tools.innerHTML='<p id="batch-tools-label" class="hint"></p><div><button class="button" type="button" data-batch-action="one">1 крафт</button><button class="button" type="button" data-batch-action="half">Половина</button><button class="button" type="button" data-batch-action="double">Вдвое</button><button class="button" type="button" id="batch-save">Сохранить вариант</button></div>';
 document.querySelector('#craft-content .flow-steps .step-card:nth-child(2) .step-heading').after(tools);
 function status(message){$('scenario-status').textContent=message}
 function selected(){const server=A.snapshot().server;return [...data.items,...(data.temporary||[])].filter(item=>data.selected.includes(item.id)&&item.server===server)}
 function paintVolume(){const x=A.snapshot(),focus=x.config.focus&&x.config.volumeMode==='focus'&&['food','potions','gear'].includes(x.recipe.kind);$('scenario-current').textContent='Текущий расчёт: '+x.recipe.name+' · '+fmt(x.result.amount,0)+' шт. · '+servers[x.server];$('batch-tools-label').textContent=focus?'Быстро изменить бюджет фокуса · '+fmt(x.config.focusBudget,0):'Быстро изменить партию · '+fmt(x.result.amount,0)+' шт.'}
 function paintList(){
  const server=A.snapshot().server;
  $('scenario-save').disabled=!!loadError||busy;
  $('scenario-list').innerHTML=data.items.length?`<div class="table-scroll"><table><thead><tr><th>Сравнить</th><th>Вариант и предмет</th><th>Сервер</th><th>Действия</th></tr></thead><tbody>${data.items.map(item=>{const r=window.ALBION_DATA.recipes.find(r=>r.id===item.recipeId);return `<tr><td><input type="checkbox" data-scenario-select="${esc(item.id)}" aria-label="Сравнить ${esc(item.name)}" ${data.selected.includes(item.id)&&item.server===server?'checked':''} ${item.server!==server||busy?'disabled':''}></td><td class="name"><b>${esc(item.name)}</b><small>${esc(r?.name||item.recipeId)} · ${esc(item.recipeId)}<br>${new Date(item.createdAt).toLocaleString('ru-RU')}</small></td><td>${servers[item.server]}</td><td><div class="scenario-row-actions"><button class="button" data-scenario-load="${esc(item.id)}" ${busy?'disabled':''}>Открыть</button><button class="button" data-scenario-delete="${esc(item.id)}" ${busy?'disabled':''}>Удалить</button></div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="scenario-empty">Сохраните текущую партию, затем измените параметры и сохраните второй вариант.</div>';
 }
 function quick(destination,name){if(loadError)throw Error(loadError);data=S.quick(localStorage,data,name,A.saveVariant(),destination);paint();return (destination==='compare'?data.temporary:data.items).at(-1)?.id;}
 function rows(){return selected().map(item=>({...A.evaluateVariant(item,market),id:item.id,name:item.name}))}
 function paintCompare(){
  lastRows=rows();const best=S.best(lastRows,$('scenario-metric').value);
  $('scenario-refresh').disabled=busy||!lastRows.length;$('scenario-refresh').textContent=busy?'Загружаем цены…':'Обновить цены сравнения';$('scenario-csv').disabled=!lastRows.length||busy;
  if(lastRows.length<2){$('scenario-comparison').innerHTML='<div class="scenario-empty">Для сравнения нужны хотя бы два отмеченных варианта на текущем сервере.</div>';return}
  const metrics=[['Количество','amount',0,'always'],['Крафтов','ops',0,'always'],['Затраты на партию','cost',2,'cost'],['Прибыль за партию','profit',2,'sale'],['Себестоимость / шт.','unitCost',2,'cost'],['Безубыток / шт.','breakEven',2,'cost'],['Прибыль / шт.','unitProfit',2,'sale'],['Доходность, %','roi',2,'sale'],['Фокус на партию','focus',0,'always']];
  $('scenario-comparison').innerHTML=`<div class="table-scroll"><table class="scenario-comparison-table"><thead><tr><th>Показатель</th>${lastRows.map(row=>`<th class="${row.id===best?'scenario-best':''}">${esc(row.name)}<small>${esc(row.recipe?.name||'Предмет не найден')} · T${row.recipe?.tier??'?'}.${row.recipe?.ench??'?'}<br>${row.id===best?'Лучший по выбранному показателю':''}</small></th>`).join('')}</tr></thead><tbody><tr><th>Готовность цен</th>${lastRows.map(row=>`<td>${row.valid?'Готов к сравнению':esc(row.reason)}</td>`).join('')}</tr>${metrics.map(([label,key,precision,type])=>`<tr><th>${label}</th>${lastRows.map(row=>`<td class="${key==='profit'||key==='unitProfit'?row.valid&&row.result[key]>=0?'positive':row.valid?'negative':'':''}">${type==='always'||type==='cost'&&row.costReady||type==='sale'&&row.valid?Number.isFinite(row.result[key])?fmt(row.result[key],precision):'—':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">Суммы указаны в серебре. «Лучший» — по одному выбранному показателю; объём продаж и риск перевозки оценивайте отдельно.</p>`;
 }
 function paint(){paintList();const temporary=data.temporary||[];if(temporary.length)$('scenario-list').insertAdjacentHTML('beforeend','<h3>Временные варианты сравнения</h3><p class="hint">Эти расчёты доступны для сравнения и не добавлены в «Мои крафты».</p><div class="table-scroll"><table><tbody>'+temporary.map(item=>'<tr><td><input type="checkbox" data-scenario-select="'+esc(item.id)+'" '+(data.selected.includes(item.id)?'checked':'')+' '+(item.server!==A.snapshot().server?'disabled':'')+'></td><td>'+esc(item.name)+'</td><td><button class="button" data-scenario-load="'+esc(item.id)+'">Открыть</button><button class="button" data-scenario-delete="'+esc(item.id)+'">Удалить</button></td></tr>').join('')+'</tbody></table></div>');paintCompare();paintVolume()}
 function tab(name){const compare=name==='compare';$('scenario-saved-panel').hidden=compare;$('scenario-compare-panel').hidden=!compare;$('scenario-saved-tab').setAttribute('aria-selected',String(!compare));$('scenario-compare-tab').setAttribute('aria-selected',String(compare));paint();}
 function open(name='saved'){status(loadError);tab(name);if(!dialog.open)dialog.showModal()}
 function save(name){if(loadError)throw Error(loadError);data=S.add(localStorage,data,name,A.saveVariant());paint();status('Вариант сохранён. Вы можете изменить параметры текущей партии.');return data.items.at(-1).id}
 function restore(id){const item=[...data.items,...(data.temporary||[])].find(x=>x.id===id);if(!item)throw Error('Вариант не найден.');if(window.Workspace)window.Workspace.open({type:'saved',id});else A.restoreVariant(item);dialog.close();paintVolume();}
 function changeVolume(action){const x=A.snapshot(),patch=S.volume(x.recipe,x.config,action);for(const [key,value]of Object.entries(patch)){const field=$(key==='volumeMode'?'volume-mode':key==='focusBudget'?'focus-budget':'quantity');field.value=value;field.dispatchEvent(new Event(field.tagName==='SELECT'?'change':'input',{bubbles:true}));}paintVolume();}
 launch.onclick=()=>open();$('scenario-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{request++;market.cancel();busy=false;});
 $('scenario-saved-tab').onclick=()=>tab('saved');$('scenario-compare-tab').onclick=()=>tab('compare');$('scenario-metric').onchange=paintCompare;
 $('batch-save').onclick=()=>{open();const x=A.snapshot();$('scenario-name').value=x.recipe.name+' · '+fmt(x.result.amount,0)+' шт.';$('scenario-name').focus();$('scenario-name').select();};
 tools.addEventListener('click',e=>{const b=e.target.closest('[data-batch-action]');if(b)changeVolume(b.dataset.batchAction)});
 $('scenario-save-form').onsubmit=e=>{e.preventDefault();try{save($('scenario-name').value);$('scenario-name').value=''}catch(error){status('Не удалось сохранить: '+error.message)}};
 $('scenario-list').addEventListener('change',e=>{const id=e.target.dataset.scenarioSelect;if(!id)return;try{const ids=selected().map(x=>x.id).filter(x=>x!==id);if(e.target.checked)ids.push(id);data=S.select(localStorage,data,ids);paintCompare()}catch(error){status(error.message);paint()}});
 $('scenario-list').addEventListener('click',e=>{try{const load=e.target.closest('[data-scenario-load]'),remove=e.target.closest('[data-scenario-delete]');if(load)restore(load.dataset.scenarioLoad);if(remove){const item=[...data.items,...(data.temporary||[])].find(x=>x.id===remove.dataset.scenarioDelete);if(window.confirm('Удалить сохранённый вариант «'+item.name+'»?')){data=S.remove(localStorage,data,item.id);paint();status('Вариант удалён.')}}}catch(error){status(error.message)}});
 $('scenario-refresh').onclick=async()=>{
  const ticket=++request;busy=true;status('Загружаем цены и историю выбранных вариантов…');paint();
  try{
   const ids=new Set();for(const row of rows()){if(!row.recipe)continue;ids.add(row.recipe.id);if(row.result.journals?.supported){ids.add(row.result.journals.empty);ids.add(row.result.journals.full);}for(const b of row.result.bill||[])ids.add(b.id);for(const stage of [{id:row.recipe.id},...row.result.stages||[]]){const r=window.ALBION_DATA.recipes.find(x=>x.id===stage.id);for(const mats of [r?.mats,...(r?.alternatives||[]).map(a=>a.mats)])for(const m of mats||[])ids.add(m.id);}}
   const error=await market.load(A.snapshot().server,[...ids],true);if(dialog.open&&ticket===request)status(error||'Цены сравнения обновлены. Ручные цены сохранены.');
  }catch(error){if(dialog.open&&ticket===request)status('Не удалось обновить: '+error.message)}finally{if(ticket===request){busy=false;if(dialog.open)paint();}}
 };
 $('scenario-csv').onclick=()=>{
  const fields=[['Название','name'],['Сервер',null],['Предмет',null],['Количество','amount'],['Крафтов','ops'],['Затраты на партию','cost'],['Прибыль на партию','profit'],['Себестоимость / шт.','unitCost'],['Прибыль / шт.','unitProfit'],['Доходность, %','roi'],['Фокус','focus'],['Готовность',null]];
  const list=[fields.map(x=>x[0]),...lastRows.map(row=>[row.name,servers[A.snapshot().server],row.recipe?.id||'',row.result.amount,row.result.ops,row.costReady?row.result.cost:'',row.valid?row.result.profit:'',row.costReady?row.result.unitCost:'',row.valid?row.result.unitProfit:'',row.valid?row.result.roi:'',row.result.focus,row.valid?'Готов':row.reason])];
  const blob=new Blob([S.csv(list)],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Albion-comparison.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);
 };
 document.addEventListener('input',paintVolume);document.addEventListener('change',paintVolume);document.addEventListener('masterychange',()=>{paintVolume();if(dialog.open)paintCompare()});paintVolume();
 window.ScenarioUI={open,save,quick,restore,changeVolume,update(id,record){const item=data.items.find(x=>x.id===id);if(!item)throw Error('Сохранённый крафт удалён.');if(loadError)throw Error(loadError);const next={...data,items:data.items.map(x=>x.id===id?{...x,...S.validate(record)}:x)};data=S.write(localStorage,next);paint();document.dispatchEvent(new Event('librarychange'));},rename(id,name){name=String(name).trim();if(!name||name.length>80)throw Error('Введите имя до 80 символов.');if(loadError)throw Error(loadError);if(!data.items.some(x=>x.id===id))throw Error('Сохранённый крафт удалён.');const next={...data,items:data.items.map(x=>x.id===id?{...x,name}:x)};data=S.write(localStorage,next);paint();document.dispatchEvent(new Event('librarychange'));},records:()=>S.clone(data),comparison:rows};
})();
